-- Reviewed runtime contracts, explicitly seeded in every environment by the seed runner.
-- No devices, products, bindings, credentials or demo instances are created here.
INSERT INTO dp_profiles (id, code, name, status) VALUES
    ('40000000-0000-0000-0000-000000000001', 'feeder-v1', 'Feeder v1', 'active'),
    ('40000000-0000-0000-0000-000000000002', 'camera-v1', 'Camera v1', 'active'),
    ('40000000-0000-0000-0000-000000000003', 'no-commands-v1', 'No commands v1', 'active')
ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name,
    status = EXCLUDED.status;

